let added = 0, skipped = 0;
for (const e of ENTRIES) {
  if (data.some((c) => c.state === e.state && c.slug === e.slug)) { skipped++; continue; }
  data.push(e);
  added++;
}
writeFileSync(path, JSON.stringify(data, null, 2));
console.log(`Batch 18: added ${added}, skipped ${skipped}, total ${data.length}`);
